/* Minerva ENTRY Web Push service worker.
 * Intentionally narrow: this worker only displays support-ticket notifications
 * generated by the server and only navigates to same-origin ENTRY ticket routes.
 */

const ENTRY_TICKET_PATH = /^\/(?:products\/entry\/tickets|field\/entry\/tickets)\/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function safeTicketPath(value) {
  if (typeof value !== "string" || value.length > 180) return null;

  try {
    const url = new URL(value, self.location.origin);
    if (url.origin !== self.location.origin) return null;
    if (url.search || url.hash) return null;
    if (!ENTRY_TICKET_PATH.test(url.pathname)) return null;
    return url.pathname;
  } catch {
    return null;
  }
}

function text(value, fallback, maxLength) {
  if (typeof value !== "string") return fallback;
  const normalized = value.trim();
  return (normalized || fallback).slice(0, maxLength);
}

self.addEventListener("push", (event) => {
  if (!event.data) return;

  let payload;
  try {
    payload = event.data.json();
  } catch {
    return;
  }

  if (!payload || typeof payload !== "object") return;
  const url = safeTicketPath(payload.url);
  if (!url) return;

  const title = text(payload.title, "ENTRY support", 90);
  const body = text(payload.body, "A support ticket needs attention.", 140);
  const tag = text(payload.tag, "entry-support", 80);

  event.waitUntil(
    self.registration.showNotification(title, {
      body,
      tag,
      renotify: true,
      data: { url },
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-192.png",
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const targetPath = safeTicketPath(event.notification?.data?.url);
  if (!targetPath) return;

  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });

      for (const client of windows) {
        try {
          const current = new URL(client.url);
          if (current.origin === self.location.origin && current.pathname === targetPath) {
            return client.focus();
          }
        } catch {
          // Ignore malformed client URLs and continue looking.
        }
      }

      return self.clients.openWindow(targetPath);
    })(),
  );
});
